body.css:
/* Glass's material: everything drawn is made of these names, and nothing
   else. Colours come in a light and a dark; type is a serif to read in and a
   sans for what stands around the reading; the measure keeps a line short
   enough to read. */

:root {
  --ground: #fbfaf7;
  --raised: #ffffff;
  --ink: #23211d;
  --quiet: #6f6a61;
  --line: #e4e0d7;
  --accent: #3d5a80;

  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --text: 18px;
  --leading: 1.6;
  --leading-close: 1.5;
  --leading-tight: 1.2;
  --lead: 1.12em;
  --aside: 0.93em;
  --code: 0.8em;
  --title: 2rem;
  --heading: 1.1rem;
  --small: 0.875rem;
  --smaller: 0.75rem;

  --measure: 40rem;
  --gap: 1rem;
  --inset: 0.8em 1em;
  --radius: 8px;
  --pill: 99px;
  --hairline: 1px;
  --rule: 3px;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ground: #171614;
    --raised: #1e1d1a;
    --ink: #e8e4dc;
    --quiet: #9b958a;
    --line: #2f2c28;
    --accent: #9db4d6;
  }
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink);
  font: var(--text) / var(--leading) var(--serif);
  -webkit-font-smoothing: antialiased;
}

#glass {
  max-width: var(--measure);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 var(--gap);
}

a {
  color: var(--accent);
}

code,
pre {
  font-family: var(--mono);
}

.glass-note {
  color: var(--quiet);
  font: var(--small) / var(--leading-close) var(--sans);
}

/* A place: what a mount draws whole. The way down to it stands above its
   title, quiet, in the sans. */

.place > nav {
  font: var(--small) / var(--leading-close) var(--sans);
  color: var(--quiet);
  margin-bottom: calc(var(--gap) * 2.5);
}

.place > nav a {
  color: inherit;
  text-decoration: none;
}

.place > nav a:hover {
  color: var(--ink);
}

.place > nav a + a::before {
  content: "›";
  margin: 0 0.5em;
  opacity: 0.6;
}

.place > h1 {
  font-size: var(--title);
  line-height: var(--leading-tight);
  font-weight: 600;
  margin: 0 0 calc(var(--gap) * 1.25);
  letter-spacing: -0.01em;
}

.place > h2 {
  font: var(--small) / var(--leading-close) var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--quiet);
  margin: calc(var(--gap) * 2.5) 0 calc(var(--gap) * 0.75);
}

.place pre {
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  padding: var(--inset);
  overflow: auto;
  max-height: 32rem;
  font-size: var(--code);
  line-height: var(--leading-close);
}

/* What is said about a thing beside it, small and quiet. */

.meta {
  display: block;
  font: var(--smaller) / var(--leading-close) var(--sans);
  color: var(--quiet);
}

/* A card: what a face slot draws, entered by a press. The slot is what is
   pressed and focused, so it is the slot that marks the card. */

.card {
  display: block;
  padding: var(--gap) calc(var(--gap) * 1.15);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  background: var(--raised);
  cursor: pointer;
  transition: border-color 0.15s;
}

.slot.face:hover > .card,
.slot.face:focus-visible > .card {
  border-color: var(--quiet);
}

.slot.face:focus-visible {
  outline: none;
}

.card .meta {
  margin-top: 0.5em;
}

/* A list: its items one under another. */

.list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: calc(var(--gap) * 0.75);
}

/* A component made of data: its mounts one under another, set off by
   space. */

.template {
  padding: calc(var(--gap) * 3) 0 calc(var(--gap) * 6);
}

.template > .slot + .slot {
  margin-top: calc(var(--gap) * 2);
}

/* A grouping's collections, side by side where there is room. */

.collections {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  gap: calc(var(--gap) * 0.75);
  margin: 0 0 calc(var(--gap) * 1.5);
}

/* A list's items as cards, side by side where there is room. */

.list.cards {
  grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr));
}

/* A search: where one stands, its parts as chips beside what is typed,
   and what is found beneath. Above what it searches from, it stays at the
   top as the page moves, and shows what it found while it holds the
   focus; in a menu, always. */

.search {
  position: relative;
  font: var(--small) / var(--leading-close) var(--sans);
}

.template > .slot:first-child:has(> .search) {
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--ground);
  padding: 0.6rem 0;
  margin-top: calc(var(--gap) * -2);
}

.search-field {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem;
  padding: 0.35rem 0.45rem;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
}

.search-field:focus-within {
  border-color: var(--quiet);
}

.search .part {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0.15em 0.25em 0.15em 0.6em;
  border: 0;
  border-radius: var(--pill);
  background: var(--line);
  color: var(--ink);
  font: inherit;
  white-space: nowrap;
}

.search button.part {
  padding-right: 0.6em;
  background: none;
  color: var(--quiet);
  cursor: pointer;
}

.search button.part:hover,
.search button.part:focus-visible {
  color: var(--ink);
  outline: none;
}

.search .part-change {
  display: inline-flex;
  gap: 0.3em;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.search .part-change:disabled {
  cursor: default;
}

.search .part-field {
  color: var(--quiet);
}

.search .part-change:not(:disabled):hover .part-value,
.search .part-change:focus-visible .part-value {
  text-decoration: underline;
  outline: none;
}

.search .part.pending {
  padding-right: 0.6em;
  background: none;
  color: var(--accent);
  font-weight: 600;
}

.search .part.pending[hidden] {
  display: none;
}

.search .let-go {
  border: 0;
  background: none;
  color: var(--quiet);
  font: inherit;
  line-height: 1;
  padding: 0 0.3em;
  border-radius: var(--pill);
  cursor: pointer;
}

.search .let-go:hover,
.search .let-go:focus-visible {
  color: var(--ink);
  background: var(--ground);
  outline: none;
}

.search-input {
  flex: 1 1 10rem;
  min-width: 8rem;
  padding: 0.25em 0.2em;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  outline: none;
}

.search-found {
  display: none;
  list-style: none;
  margin: 0.3rem 0 0;
  padding: 0.3rem;
  max-height: min(24rem, 60vh);
  overflow-y: auto;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
}

.search:focus-within .search-found:not(:empty),
.search.pressed .search-found:not(:empty) {
  display: block;
}

.slot:not(.menu *) > .search .search-found {
  position: absolute;
  left: 0;
  right: 0;
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.12);
}

.found {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: calc(var(--radius) - 2px);
}

.found.active,
.found:hover {
  background: var(--ground);
}

.found .lead {
  flex: 1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  min-width: 0;
  padding: 0.4rem 0.55rem;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.found-said {
  display: block;
  padding: 0.4rem 0.55rem;
  color: var(--quiet);
}

.found-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.found .meta {
  flex-shrink: 0;
  max-width: 50%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A mount's menu: the search, laid where the press landed. */

.menu {
  position: fixed;
  z-index: 10;
  width: min(30rem, calc(100vw - 16px));
  padding: 0.35rem;
  background: var(--ground);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.18);
}
